  // initialized. Enumerate lower tiles row-major over (ly, lx), lx < ly.
  if (bid < lower_tiles) {
    int ly = 0;
    int lrem = bid;
    while (lrem > ly) {
      lrem -= (ly + 1);
      ++ly;
    }
    const int lx = lrem;
    auto zcoord = make_coord(lx, ly, _);
    Tensor gZ = local_tile(mC, cta_tiler, zcoord, Step<_1,_1,X>{});
    Tensor tCgZ = local_partition(gZ, tC, threadIdx.x, Step<_1,_1>{});
    for (int i = 0; i < size(tCgZ); ++i) {
      tCgZ(i) = TC(0);
    }
  }
}

// Host wrapper
